import { parseNote } from '../parse/line.js';
import { createStore } from '../store/store.js';
import { parseArgs } from './args.js';
import { formatNote } from './format.js';

// Runs one command and returns the exit code.
export function main(argv, { file, out }) {
  const [command, ...rest] = argv;
  const store = createStore(file);
  try {
    switch (command) {
      case 'add': {
        const saved = store.add(parseNote(rest.join(' ')));
        out('added ' + saved.id);
        return 0;
      }
      case 'list': {
        const { flags } = parseArgs(rest, ['tag']);
        for (const note of store.list({ tag: flags.tag })) out(formatNote(note));
        return 0;
      }
      case 'tags': {
        for (const { tag, count } of store.tags()) out(tag + ' ' + count);
        return 0;
      }
      case 'done':
      case 'rm': {
        const id = Number(rest[0]);
        const ok = command === 'done' ? store.setDone(id) : store.remove(id);
        if (!ok) throw new RangeError('no such note: ' + rest[0]);
        out(command === 'done' ? 'done ' + id : 'removed ' + id);
        return 0;
      }
      default:
        out('usage: notes <add|list|tags|done|rm> ...');
        return 1;
    }
  } catch (error) {
    out('error: ' + error.message);
    return 1;
  }
}

// One listed note: "3 [ ] Buy milk" or "3 [ ] Buy milk  #home #errands".
export function formatNote(note) {
  const line = note.id + ' [' + (note.done ? 'x' : ' ') + '] ' + note.text;
  const tags = note.tags ?? [];
  return tags.length ? line + '  ' + tags.map((tag) => '#' + tag).join(' ') : line;
}

import { words } from './tokens.js';

const TAG = /^#([a-z0-9_-]+)$/i;

// Turns a typed line into a note: { text, tags, done }. `#word` tokens
// become lowercase tags (first appearance wins) and leave the text.
export function parseNote(line) {
  const tags = [];
  const rest = [];
  for (const word of words(line)) {
    const match = TAG.exec(word);
    if (!match) rest.push(word);
    else if (!tags.includes(match[1].toLowerCase())) tags.push(match[1].toLowerCase());
  }
  const text = rest.join(' ');
  if (!text) throw new TypeError('note text must not be empty');
  return { text, tags, done: false };
}

import { readJson, writeJson } from './storage.js';

export function createStore(file) {
  const load = () => readJson(file, { nextId: 1, notes: [] });
  const find = (data, id) => data.notes.find((note) => note.id === id);
  const withTags = (note) => ({ ...note, tags: note.tags ?? [] });
  return {
    add(note) {
      const data = load();
      const saved = {
        id: data.nextId,
        text: note.text,
        tags: [...(note.tags ?? [])],
        done: false,
      };
      data.nextId += 1;
      data.notes.push(saved);
      writeJson(file, data);
      return saved;
    },
    list({ tag } = {}) {
      const notes = load().notes.map(withTags);
      if (tag === undefined) return notes;
      return notes.filter((note) => note.tags.includes(tag.toLowerCase()));
    },
    // Tags in use with their note counts: most used first, then by name.
    tags() {
      const counts = new Map();
      for (const note of load().notes.map(withTags))
        for (const tag of note.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
      return [...counts]
        .map(([tag, count]) => ({ tag, count }))
        .sort((a, b) => b.count - a.count || (a.tag < b.tag ? -1 : 1));
    },
    setDone(id) {
      const data = load();
      const note = find(data, id);
      if (!note) return false;
      note.done = true;
      writeJson(file, data);
      return true;
    },
    remove(id) {
      const data = load();
      const before = data.notes.length;
      data.notes = data.notes.filter((note) => note.id !== id);
      writeJson(file, data);
      return data.notes.length < before;
    },
  };
}
